import { BaseElement } from '../common/base-element';
import { resolveOverlayBaseUrl, resolveSupabaseKey, resolveSupabaseUrl } from '../common/runtime-config';
import './bulb/rg-bulb';
import { buildBulbEmbedCode } from './bulb/embed-snippet';
import { modalStyles } from './styles/modals';
import {
  buildOverlayUrl,
  TEST_DONATION_MESSAGE,
  type BulbPosition,
  type SoundName,
  type ToastPosition,
} from '../stream-overlay/config';

// Two dialogs on a campaign page: "Embed widget" (a live bulb preview and the snippet to copy) and
// "Stream overlay" (settings, a live preview iframe, a Test donation button, and the URL to use as a browser source).
// Only one is open at a time. Each is a custom element with its own Shadow DOM, appended to <body>.

const TEST_DONOR_NAMES = ['Resplendent Capybara', 'Magnificent Quokka', 'Jamie R.', 'Alex Chen', 'Dauntless Otter'];
const TEST_AMOUNTS = [5, 10, 20, 25, 50, 100];

abstract class ModalElement extends BaseElement {
  constructor() {
    // Controls take the page's font (the same isolation rule as the other components), not the browser's.
    super(`button, input { font-family: inherit; }\n${modalStyles}`);
  }

  /** Called by the dialog when it is dismissed. */
  onClose: (() => void) | null = null;

  protected wireDismiss(): void {
    const overlay = this.$('.embed-modal-overlay');
    overlay?.addEventListener('click', (e) => {
      if (e.target === overlay) this.onClose?.();
    });
    this.$('.embed-modal-close')?.addEventListener('click', () => this.onClose?.());
  }

  focusClose(): void {
    this.$<HTMLButtonElement>('.embed-modal-close')?.focus();
  }

  /** Copy `source`'s text, falling back to the old selection API; flashes "Copied!". */
  protected wireCopy(button: HTMLElement, source: HTMLInputElement | HTMLTextAreaElement): void {
    button.addEventListener('click', () => {
      source.select();
      source.setSelectionRange(0, source.value.length);
      const showCopied = () => {
        button.textContent = 'Copied!';
        button.classList.add('embed-copy-btn--copied');
        setTimeout(() => {
          button.textContent = 'Copy';
          button.classList.remove('embed-copy-btn--copied');
        }, 1800);
      };
      const legacy = () => {
        document.execCommand('copy');
        showCopied();
      };
      if (navigator.clipboard?.writeText) navigator.clipboard.writeText(source.value).then(showCopied).catch(legacy);
      else legacy();
    });
  }
}

export class RgEmbedModal extends ModalElement {
  slug = '';

  connectedCallback(): void {
    const code = buildBulbEmbedCode({
      slug: this.slug,
      siteUrl: window.location.origin,
      supabaseUrl: resolveSupabaseUrl(),
      supabaseKey: resolveSupabaseKey(),
      overlayBaseUrl: resolveOverlayBaseUrl(),
    });
    this.setHtml(`
      <div class="embed-modal-overlay">
        <div class="embed-modal" role="dialog" aria-modal="true" aria-labelledby="embed-modal-title">
          <div class="embed-modal-header">
            <div>
              <p class="embed-modal-title" id="embed-modal-title">Embed this campaign's progress</p>
              <p class="embed-modal-subtitle">Paste it anywhere — your site, a Twitch panel, wherever</p>
            </div>
            <button type="button" class="embed-modal-close" aria-label="Close">&times;</button>
          </div>
          <div class="embed-modal-body">
            <div class="embed-preview"></div>
            <p class="embed-code-label">Embed code</p>
            <div class="embed-code-row">
              <textarea class="embed-textarea" readonly spellcheck="false" aria-label="Embed code"></textarea>
              <button type="button" class="embed-copy-btn">Copy</button>
            </div>
            <p class="embed-modal-hint">Paste this anywhere that allows custom HTML. It keeps itself up to date — no need to re-copy it as donations come in.</p>
          </div>
        </div>
      </div>`);
    const textarea = this.$<HTMLTextAreaElement>('.embed-textarea')!;
    textarea.value = code;
    const bulb = document.createElement('rg-bulb');
    bulb.setAttribute('slug', this.slug);
    this.$('.embed-preview')!.appendChild(bulb);
    this.wireDismiss();
    this.wireCopy(this.$('.embed-copy-btn')!, textarea);
  }
}

interface OverlayState {
  bulbPos: BulbPosition;
  bulbScale: number;
  toastPos: ToastPosition;
  toastScale: number;
  toastTheme: 'dark' | 'light';
  toastDuration: number;
  sound: SoundName;
}

export class RgOverlayModal extends ModalElement {
  slug = '';

  connectedCallback(): void {
    this.setHtml(`
      <div class="embed-modal-overlay">
        <div class="embed-modal ov-modal" role="dialog" aria-modal="true" aria-labelledby="ov-modal-title">
          <div class="embed-modal-header">
            <div>
              <p class="embed-modal-title" id="ov-modal-title">Stream overlay</p>
              <p class="embed-modal-subtitle">Add as a Browser Source in OBS, Streamlabs, or similar</p>
            </div>
            <button type="button" class="embed-modal-close" aria-label="Close">&times;</button>
          </div>
          <div class="embed-modal-body">
            <div class="ov-preview-wrap">
              <iframe class="ov-preview-frame" title="Overlay preview" allow="autoplay"></iframe>
            </div>
            <div class="ov-controls">
              <div class="ov-field">
                <label>Bulb position</label>
                <select class="ov-bulb-pos">
                  <option value="bottom-right">Bottom right</option>
                  <option value="bottom-left">Bottom left</option>
                  <option value="top-right">Top right</option>
                  <option value="top-left">Top left</option>
                  <option value="center">Center</option>
                  <option value="hidden">Hidden</option>
                </select>
              </div>
              <div class="ov-field">
                <label>Bulb size <span class="ov-field-value ov-bulb-scale-val">100%</span></label>
                <input type="range" class="ov-bulb-scale" min="50" max="200" step="5" value="100" />
              </div>
              <div class="ov-field">
                <label>Donation toast position</label>
                <select class="ov-toast-pos">
                  <option value="top-right">Top right</option>
                  <option value="top-left">Top left</option>
                  <option value="bottom-right">Bottom right</option>
                  <option value="bottom-left">Bottom left</option>
                  <option value="top-center">Top center</option>
                  <option value="bottom-center">Bottom center</option>
                  <option value="hidden">Hidden</option>
                </select>
              </div>
              <div class="ov-field">
                <label>Toast size <span class="ov-field-value ov-toast-scale-val">100%</span></label>
                <input type="range" class="ov-toast-scale" min="50" max="200" step="10" value="100" />
              </div>
              <div class="ov-field">
                <label>Toast theme</label>
                <select class="ov-toast-theme">
                  <option value="dark">Dark (fits most backgrounds)</option>
                  <option value="light">Light</option>
                </select>
              </div>
              <div class="ov-field">
                <label>Toast duration <span class="ov-field-value ov-toast-duration-val">6s</span></label>
                <input type="range" class="ov-toast-duration" min="1" max="11" step="1" value="6" />
              </div>
              <div class="ov-field">
                <label>Donation sound</label>
                <select class="ov-sound-select">
                  <option value="locomotive">Locomotive</option>
                  <option value="none">None</option>
                </select>
              </div>
              <div class="ov-field ov-field--action">
                <button type="button" class="ov-test-btn">🎉 Test donation</button>
              </div>
            </div>
            <p class="embed-code-label">Overlay URL — paste into your streaming software as a Browser Source</p>
            <div class="embed-code-row">
              <input type="text" class="ov-url-input" readonly aria-label="Overlay URL" />
              <button type="button" class="embed-copy-btn ov-copy-btn">Copy</button>
            </div>
            <p class="embed-modal-hint">Recommended Browser Source size: 1920×1080, with "Refresh browser when scene becomes active" and a transparent background enabled. It updates itself — no need to re-copy it as the campaign progresses.</p>
          </div>
        </div>
      </div>`);

    const q = <T extends HTMLElement>(sel: string) => this.$<T>(sel)!;
    const iframe = q<HTMLIFrameElement>('.ov-preview-frame');
    const urlInput = q<HTMLInputElement>('.ov-url-input');
    const state: OverlayState = {
      bulbPos: 'bottom-right', bulbScale: 100, toastPos: 'top-right', toastScale: 100,
      toastTheme: 'dark', toastDuration: 6, sound: 'locomotive',
    };

    const update = () => {
      const url = buildOverlayUrl(resolveOverlayBaseUrl(), this.slug, resolveSupabaseUrl(), resolveSupabaseKey(), {
        bulbPos: state.bulbPos,
        bulbScale: (state.bulbScale / 100).toFixed(2),
        toastPos: state.toastPos,
        toastScale: (state.toastScale / 100).toFixed(2),
        toastTheme: state.toastTheme,
        toastDuration: state.toastDuration,
        sound: state.sound,
      });
      urlInput.value = url;
      iframe.src = url; // a full reload: the overlay reads its configuration once, when it loads
    };

    const select = (sel: string, apply: (v: string) => void) =>
      q<HTMLSelectElement>(sel).addEventListener('change', (e) => {
        apply((e.target as HTMLSelectElement).value);
        update();
      });
    const range = (sel: string, label: string, suffix: string, apply: (n: number) => void) =>
      q<HTMLInputElement>(sel).addEventListener('input', (e) => {
        const n = parseInt((e.target as HTMLInputElement).value, 10);
        apply(n);
        q(label).textContent = n + suffix;
        update();
      });

    select('.ov-bulb-pos', (v) => (state.bulbPos = v as BulbPosition));
    range('.ov-bulb-scale', '.ov-bulb-scale-val', '%', (n) => (state.bulbScale = n));
    select('.ov-toast-pos', (v) => (state.toastPos = v as ToastPosition));
    range('.ov-toast-scale', '.ov-toast-scale-val', '%', (n) => (state.toastScale = n));
    select('.ov-toast-theme', (v) => (state.toastTheme = v as 'dark' | 'light'));
    range('.ov-toast-duration', '.ov-toast-duration-val', 's', (n) => (state.toastDuration = n));
    select('.ov-sound-select', (v) => (state.sound = v as SoundName));

    q('.ov-test-btn').addEventListener('click', () => {
      if (!iframe.contentWindow) return;
      iframe.contentWindow.postMessage(
        {
          type: TEST_DONATION_MESSAGE,
          name: TEST_DONOR_NAMES[Math.floor(Math.random() * TEST_DONOR_NAMES.length)],
          amount: TEST_AMOUNTS[Math.floor(Math.random() * TEST_AMOUNTS.length)],
          currency: 'usd',
          recurring: Math.random() < 0.3,
        },
        '*',
      );
    });

    this.wireDismiss();
    this.wireCopy(q('.ov-copy-btn'), urlInput);
    update();
  }
}

if (!customElements.get('rg-embed-modal')) customElements.define('rg-embed-modal', RgEmbedModal);
if (!customElements.get('rg-overlay-modal')) customElements.define('rg-overlay-modal', RgOverlayModal);

// ── Opening and closing (one dialog at a time) ───────────────────────────────

let open: { el: ModalElement; trigger: HTMLElement | null; onKeydown: (e: KeyboardEvent) => void } | null = null;

export function closeModal(): void {
  if (!open) return;
  document.removeEventListener('keydown', open.onKeydown);
  open.el.remove();
  document.body.style.overflow = '';
  const trigger = open.trigger;
  open = null;
  if (trigger && typeof trigger.focus === 'function') trigger.focus();
}

function show(el: ModalElement, trigger: HTMLElement | null): void {
  closeModal();
  const onKeydown = (e: KeyboardEvent) => {
    if (e.key === 'Escape') closeModal();
  };
  el.onClose = closeModal;
  document.addEventListener('keydown', onKeydown);
  document.body.appendChild(el);
  document.body.style.overflow = 'hidden';
  el.focusClose();
  open = { el, trigger, onKeydown };
}

export function openEmbedModal(slug: string, trigger: HTMLElement | null): void {
  const el = document.createElement('rg-embed-modal') as RgEmbedModal;
  el.slug = slug;
  show(el, trigger);
}

export function openOverlayModal(slug: string, trigger: HTMLElement | null): void {
  const el = document.createElement('rg-overlay-modal') as RgOverlayModal;
  el.slug = slug;
  show(el, trigger);
}
