// The stream overlay's query-string contract, in one place.
//
// CONTRACT (CLAUDE.md): streamers have these URLs saved in their streaming software. The parameter names, accepted
// values, defaults and clamps below must keep meaning exactly what they have always meant:
//   slug, supabaseUrl, supabaseAnonKey, bulbPos, bulbScale, toastPos, toastScale, toastTheme,
//   toastDuration, sound, wiggle, debug, test
// The URL builder (used by the "Stream overlay" modal on a campaign page) and the parser (used by
// the overlay) both live here, so they cannot drift apart. config.test.ts pins the behavior.

export const BULB_POSITIONS = ['top-left', 'top-right', 'bottom-left', 'bottom-right', 'center', 'hidden'] as const;
export const TOAST_POSITIONS = ['top-left', 'top-right', 'bottom-left', 'bottom-right', 'top-center', 'bottom-center', 'hidden'] as const;
export const SOUNDS = ['locomotive', 'none'] as const;

export type BulbPosition = (typeof BULB_POSITIONS)[number];
export type ToastPosition = (typeof TOAST_POSITIONS)[number];
export type SoundName = (typeof SOUNDS)[number];

export interface OverlayConfig {
  slug: string;
  supabaseUrl: string;
  supabaseAnonKey: string;
  bulbPos: BulbPosition;
  bulbScale: number;
  toastPos: ToastPosition;
  toastScale: number;
  toastDuration: number;
  toastTheme: 'dark' | 'light';
  sound: SoundName;
  wiggle: boolean;
  debug: boolean;
  test: boolean;
}

const clamp = (n: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, n));

function oneOf<T extends string>(set: readonly T[], value: string | null, fallback: T): T {
  return value !== null && (set as readonly string[]).includes(value) ? (value as T) : fallback;
}

/** Read the overlay's settings from a query string (`location.search`). */
export function parseOverlayConfig(search: string): OverlayConfig {
  const params = new URLSearchParams(search);
  return {
    slug: params.get('slug') || '',
    supabaseUrl: (params.get('supabaseUrl') || '').replace(/\/$/, ''),
    supabaseAnonKey: params.get('supabaseAnonKey') || '',
    bulbPos: oneOf(BULB_POSITIONS, params.get('bulbPos'), 'bottom-right'),
    bulbScale: clamp(parseFloat(params.get('bulbScale') ?? '') || 1, 0.5, 2),
    toastPos: oneOf(TOAST_POSITIONS, params.get('toastPos'), 'top-right'),
    toastScale: clamp(parseFloat(params.get('toastScale') ?? '') || 1, 0.25, 2),
    toastDuration: clamp(parseFloat(params.get('toastDuration') ?? '') || 6, 1, 15),
    toastTheme: params.get('toastTheme') === 'light' ? 'light' : 'dark',
    sound: oneOf(SOUNDS, params.get('sound'), 'locomotive'),
    wiggle: params.get('wiggle') !== '0',
    debug: params.get('debug') === '1',
    test: params.get('test') === '1',
  };
}

/** True when the page was opened with no configuration at all (shows the setup hint). */
export function hasNoConfig(c: OverlayConfig): boolean {
  return !c.slug && !c.supabaseUrl && !c.supabaseAnonKey;
}

export interface OverlayUrlOptions {
  bulbPos: BulbPosition;
  /** Already formatted, e.g. "1.50". */
  bulbScale: string;
  toastPos: ToastPosition;
  toastScale: string;
  toastTheme: 'dark' | 'light';
  toastDuration: number;
  sound: SoundName;
}

/** Where the overlay lives: the root of the overlay host, under its permanent file name. */
export function overlayFileUrl(overlayBaseUrl: string): string {
  return `${overlayBaseUrl.replace(/\/$/, '')}/stream-overlay.html`;
}

/** The URL a streamer adds as a browser source. Parameter order is kept as in production. */
export function buildOverlayUrl(
  overlayBaseUrl: string,
  slug: string,
  supabaseUrl: string,
  supabaseAnonKey: string,
  opts: OverlayUrlOptions,
): string {
  const u = new URL(overlayFileUrl(overlayBaseUrl));
  u.searchParams.set('slug', slug);
  u.searchParams.set('supabaseUrl', supabaseUrl);
  u.searchParams.set('supabaseAnonKey', supabaseAnonKey);
  u.searchParams.set('bulbPos', opts.bulbPos);
  u.searchParams.set('bulbScale', opts.bulbScale);
  u.searchParams.set('toastPos', opts.toastPos);
  u.searchParams.set('toastScale', opts.toastScale);
  u.searchParams.set('toastTheme', opts.toastTheme);
  u.searchParams.set('toastDuration', String(opts.toastDuration));
  u.searchParams.set('sound', opts.sound);
  return u.toString();
}

/** The message the modal's preview sends to the overlay iframe to show a fake donation. */
export const TEST_DONATION_MESSAGE = 'sb-overlay-test-donation';
