import { BaseElement } from '../common/base-element';
import '../donations/index'; // the donation form, recent donations and leaderboard it shows
import './progress-bar';
import type { Campaign } from './api';
import { formatCents, mountCountdown } from './format';
import { openEmbedModal, openOverlayModal } from './modals';
import { cssImageUrl, escapeHtml, safeHttpUrl } from './safe';
import { OFFICIAL_RIBBON_HTML, ribbonStyles } from './ribbon';
import { iconSvg, SOCIAL_ICON_MAP } from './social-icons';
import { detailStyles } from './styles/detail';

// Production laid the grid out with `.cd-donate .dw-wrap { max-width: none; ... }`. The widgets'
// cards are inside their own Shadow DOM here, so the same override goes through their `wrap` part.
const PART_OVERRIDES = `
:host { display: block; }
.cd-donate rg-donation-form::part(wrap),
.cd-recent rg-recent-donations::part(wrap),
.cd-leaderboard rg-leaderboard::part(wrap) { max-width: none; width: 100%; margin: 0; }
.cd-icon { display: block; }
.cd-embed-btn, .cd-social-link { font-family: inherit; }
.cd-embed-btn .cd-icon { font-size: 0.95em; }
`;

function socialIcon(label: string, url: unknown): string {
  const href = safeHttpUrl(url);
  if (!href) return '';
  const icon = SOCIAL_ICON_MAP[label];
  if (icon) {
    return `<a href="${escapeHtml(href)}" target="_blank" rel="noopener noreferrer" class="cd-social-icon" aria-label="${escapeHtml(label)}">${iconSvg(icon)}</a>`;
  }
  // A custom "other" link has no icon to guess at: a text pill, as before.
  return `<a class="cd-social-link" href="${escapeHtml(href)}" target="_blank" rel="noopener noreferrer">${escapeHtml(label)}</a>`;
}

/**
 * <rg-campaign-detail>: the body of a campaign page (/fundraising-campaigns/p/<slug>): an info card
 * (image, name, organizer, countdown, description, goal, embed/overlay buttons, social links,
 * progress bar) next to the donation form, then recent donations and the leaderboard.
 * Set `campaign` for the page; set `notFound` instead for the "could not be found" message.
 * The page's native product markup is hidden by the site loader, not here.
 */
export class RgCampaignDetail extends BaseElement {
  private _campaign: Campaign | null = null;
  private _notFound = false;
  /** An image Squarespace rendered natively, used when the campaign has none of its own. */
  fallbackImageUrl = '';
  private stopCountdown: (() => void) | undefined;

  constructor() {
    super(`${PART_OVERRIDES}\n${ribbonStyles}\n${detailStyles}`);
  }

  set campaign(value: Campaign | null) {
    this._campaign = value;
    if (this.isConnected) this.render();
  }

  set notFound(value: boolean) {
    this._notFound = value;
    if (this.isConnected) this.render();
  }

  connectedCallback(): void {
    this.render();
  }

  disconnectedCallback(): void {
    this.stopCountdown?.();
  }

  private render(): void {
    this.stopCountdown?.();
    const c = this._campaign;
    if (!c) {
      this.setHtml(
        this._notFound
          ? '<p class="cd-not-found">This campaign could not be found. It may have ended or the link may be incorrect.</p>'
          : '',
      );
      return;
    }

    const socials =
      socialIcon('Twitch', c.twitch_url) +
      socialIcon('YouTube', c.youtube_url) +
      socialIcon('TikTok', c.tiktok_url) +
      socialIcon('Instagram', c.instagram_url) +
      socialIcon('Discord', c.discord_url) +
      (c.other_links ?? []).map((l) => socialIcon(l.label, l.url)).join('');

    const slug = escapeHtml(c.slug);
    const id = escapeHtml(c.id);
    // DOM order is the mobile reading order (info, donate, recent, leaderboard); the desktop 2x2
    // placement comes from grid-template-areas in the CSS.
    this.setHtml(`
      <div class="cd-grid">
        <div class="cd-info"><div class="cd-info-card">
          <div class="cd-info-image rg-ribbon-host">${c.is_official ? OFFICIAL_RIBBON_HTML : ''}</div>
          <div class="cd-info-body">
            <div class="cd-title-row">
              <h1 class="cd-title">${escapeHtml(c.name)}</h1>
              <span class="cd-countdown-badge" id="cd-countdown"></span>
            </div>
            <p class="cd-organizer">Organized by ${escapeHtml(c.organizer_name)}</p>
            <p class="cd-description">${escapeHtml(c.description)}</p>
            <div class="cd-goal-row">
              <p class="cd-goal">Goal: ${formatCents(c.goal_cents)}</p>
              <div class="cd-goal-row-actions">
                <button type="button" class="cd-embed-btn" id="cd-embed-btn">${iconSvg('code')}<span>Embed widget</span></button>
                <button type="button" class="cd-embed-btn" id="cd-overlay-btn">${iconSvg('tv')}<span>Stream overlay</span></button>
              </div>
            </div>
            ${socials ? `<nav class="cd-socials">${socials}</nav>` : ''}
            <div id="campaign-progress"><rg-progress-bar slug="${slug}" campaign-id="${id}"></rg-progress-bar></div>
          </div>
        </div></div>
        <div class="cd-donate" id="campaign-donate-widget"><rg-donation-form campaign-slug="${slug}"></rg-donation-form></div>
        <div class="cd-recent" id="campaign-recent"><rg-recent-donations campaign-id="${id}"></rg-recent-donations></div>
        <div class="cd-leaderboard" id="campaign-leaderboard"><rg-leaderboard campaign-id="${id}"></rg-leaderboard></div>
      </div>`);

    // Prefer the campaign's own image; fall back to the one Squarespace rendered natively.
    const image = cssImageUrl(c.image_url || this.fallbackImageUrl);
    if (image) this.$<HTMLElement>('.cd-info-image')!.style.backgroundImage = image;

    this.stopCountdown = mountCountdown(this.$('#cd-countdown'), c.target_date, 30000);
    this.$<HTMLElement>('#cd-embed-btn')!.addEventListener('click', (e) => openEmbedModal(c.slug, e.currentTarget as HTMLElement));
    this.$<HTMLElement>('#cd-overlay-btn')!.addEventListener('click', (e) => openOverlayModal(c.slug, e.currentTarget as HTMLElement));

    // Stripe sends donors back to `#thank-you`: bring the live feed and leaderboard into view.
    if (window.location.hash === '#thank-you') {
      setTimeout(() => this.$('.cd-recent')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 400);
    }
  }
}

if (!customElements.get('rg-campaign-detail')) customElements.define('rg-campaign-detail', RgCampaignDetail);
