/**
 * An inline <svg> for an icon, one em tall and as wide as Font Awesome draws that glyph
 * (viewBox width / 512 em, so a 640-wide glyph is 1.25em), decorative.
 */
export function iconSvg(name: keyof typeof ICONS): string {
  const icon = ICONS[name];
  const widthEm = Number(icon.viewBox.split(' ')[2]) / 512;
  return `<svg class="cd-icon" viewBox="${icon.viewBox}" width="${widthEm}em" height="1em" fill="currentColor" aria-hidden="true" focusable="false"><path d="${icon.path}"/></svg>`;
}

