import { createBulbController } from './controller';
import {
  BULB_GLASS_BOTTOM,
  BULB_GLASS_TOP,
  BULB_PALETTE,
  BULB_WIDTH_SAMPLES,
  calculateLap,
  createBulbGeometry,
  paletteColorOf,
} from './geometry';
import { bulbIds, bulbSvg, type BulbIds } from './svg';
import { bulbCss, bulbFontFace } from './styles';

export interface EmbedOptions {
  slug: string;
  /** The campaign page's origin, no trailing slash: where the widget links to. */
  siteUrl: string;
  supabaseUrl: string;
  supabaseKey: string;
  /** Where the brand font files are served from (the overlay host's root), no trailing slash. */
  overlayBaseUrl: string;
}

/**
 * The fully self-contained embed snippet: a fragment (no <html>/<body>) to paste anywhere that
 * allows custom HTML (a Twitch panel, a WordPress block). It carries its own styles and script and
 * every id is namespaced by the slug, so it can be pasted more than once on a page.
 *
 * The maths and the animation are not rewritten here: the snippet embeds the source text of the
 * same functions the on-page widget runs (geometry.ts, controller.ts).
 *
 * CONTRACT (CLAUDE.md): snippets already pasted on other sites poll
 * `GET {supabaseUrl}/rest/v1/rpc/campaign_progress?p_slugs={slug}` with the apikey and
 * Authorization headers; this one makes the same call.
 */
export function buildBulbEmbedCode(o: EmbedOptions): string {
  // The slug is spliced into markup, CSS and script: only what create-campaign itself accepts.
  if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(o.slug)) throw new Error('Invalid campaign slug');
  const json = (v: unknown) => JSON.stringify(v).replace(/</g, '\\u003c'); // never a literal "</script"
  const id = `rga-bulb-${o.slug}`;
  const ids: BulbIds = bulbIds(id);
  const family = `RealGoodFont-${id}`;
  const css =
    bulbFontFace(family, o.overlayBaseUrl) +
    bulbCss({ root: `#${id}`, fontFamily: `"${family}"`, keyframes: id, rootFont: true });

  const config = {
    campaignSlug: o.slug,
    siteUrl: o.siteUrl,
    supabaseUrl: o.supabaseUrl,
    supabaseAnonKey: o.supabaseKey,
    pollIntervalMs: 60000,
  };

  // `<\/script>`: this string ends up in HTML, so a literal closing tag would end the snippet.
  const script = `(function () {
  "use strict";
  var CONFIG = ${json(config)};
  var PALETTE = ${json(BULB_PALETTE)};
  var calculateLap = ${calculateLap.toString()};
  var paletteColorOf = ${paletteColorOf.toString()};
  var createBulbGeometry = ${createBulbGeometry.toString()};
  var createBulbController = ${createBulbController.toString()};

  var geometry = createBulbGeometry(${json(BULB_WIDTH_SAMPLES)}, ${BULB_GLASS_TOP}, ${BULB_GLASS_BOTTOM});
  var linkEl = document.getElementById(${json(id)});
  linkEl.href = CONFIG.siteUrl.replace(/\\/$/, "") + "/fundraising-campaigns/p/" + CONFIG.campaignSlug;
  var bulb = createBulbController({
    wiggle: document.getElementById(${json(id + '-wiggle')}),
    baseFill: document.getElementById(${json(ids.baseFill)}),
    liquid: document.getElementById(${json(ids.liquid)}),
    waveA: document.getElementById(${json(ids.waveA)}),
    waveB: document.getElementById(${json(ids.waveB)}),
    amount: document.getElementById(${json(ids.amount)})
  }, { geometry: geometry, palette: PALETTE, calculateLap: calculateLap, paletteColorOf: paletteColorOf });

  function tick() {
    var url = CONFIG.supabaseUrl + "/rest/v1/rpc/campaign_progress?p_slugs={" + encodeURIComponent(CONFIG.campaignSlug) + "}";
    fetch(url, { headers: { apikey: CONFIG.supabaseAnonKey, Authorization: "Bearer " + CONFIG.supabaseAnonKey } })
      .then(function (res) { return res.json(); })
      .then(function (rows) { if (rows && rows.length) bulb.render(rows[0].raised_cents, rows[0].goal_cents); })
      .catch(function (err) { console.error("[bulb widget] failed to load campaign progress", err); });
  }
  tick();
  setInterval(tick, CONFIG.pollIntervalMs);
})();`;

  return `<!-- Real Good AI campaign progress widget — safe to paste anywhere -->
<style>${css}</style>
<a id="${id}" href="#" target="_blank" rel="noopener" aria-label="Campaign donation progress — click to view campaign">
  <div class="bulb-card" id="${id}-card">
    <div class="bulb-wiggle-wrap" id="${id}-wiggle">
    ${bulbSvg(ids)}
    </div>
  </div>
</a>
<script>
${script}
${'<'}/script>`;
}
